// Pulls the JSON object out of Claude's reply and turns it into what is written to the sheet (Nil's decisions of
// 23 Nov 2026, sections 4 to 6 and 13): segment and wave, size and criteria fit, decision maker and second contact.
// Output: { output, update (columns for the lead row), child (row for the second contact, or null), error }.
const lead = $('Limit 10').all()[$runIndex].json;
const backfill = lead._mode === 'backfill';
const existingIds = new Set($('Get New Leads').all().map(i => String((i.json || {})['Lead ID'] || '').trim()));
const keys = ['research_notes', 'personalisation_hook', 'segment_class', 'product_type', 'employees', 'export_volume', 'export_usd_m', 'contact_name', 'contact_title', 'email', 'linkedin', 'contact_role', 'contact_source', 'contact2_name', 'contact2_title', 'contact2_email', 'contact2_linkedin', 'contact2_source', 'general_email'];
function strings(v, acc) {
  if (typeof v === 'string') acc.push(v);
  else if (Array.isArray(v)) v.forEach(x => strings(x, acc));
  else if (v && typeof v === 'object') Object.values(v).forEach(x => strings(x, acc));
  return acc;
}
function extract(text) {
  const s = text.indexOf('{'); const e = text.lastIndexOf('}');
  if (s < 0 || e <= s) return null;
  for (let end = e; end > s; end = text.lastIndexOf('}', end - 1)) {
    try { const o = JSON.parse(text.slice(s, end + 1)); if (o && typeof o === 'object') return o; } catch (err) { /* try a shorter slice */ }
  }
  return null;
}
const SEG = {
  garment: ['Hazır giyim / konfeksiyon', '1'],
  integrated: ['Entegre tesis', '1'],
  fabric_yarn_dye: ['Kumaş / iplik / boyahane', '2'],
  home_textile: ['Ev tekstili', '2'],
  workwear: ['İş kıyafeti', '2'],
  sourcing_office: ['Sourcing ofisi', 'Ayrı liste'],
  brand: ['Marka', '1'],
  excluded: ['Hariç', 'Hariç'],
};
const num = (v) => { const n = Number(String(v == null ? '' : v).replace(/[^\d.]/g, '')); return Number.isFinite(n) && n > 0 ? n : null; };
const isEmail = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);
const source = (v, hasPerson) => {
  if (!hasPerson) return 'Genel adres';
  const s = String(v || '').toLowerCase();
  if (s.includes('linkedin')) return 'LinkedIn';
  if (/press|basın|basin|news|haber/.test(s)) return 'Basın';
  return 'Web sitesi';
};
const now = $now.toISO();

const body = $input.item.json || {};
let parsed = null;
let error = '';
if (body.error && !body.content && !body.merged) error = String(body.error.message || body.error).slice(0, 500);
else {
  const texts = strings(body, []).filter(t => t.includes('personalisation_hook'));
  for (const t of texts) { parsed = extract(t); if (parsed) break; }
  if (!parsed) error = 'No JSON in reply: ' + strings(body, []).join(' ').slice(0, 400);
}
const o = {};
for (const k of keys) o[k] = String((parsed || {})[k] ?? '').trim();
// Titles go into the sheet and ClickUp as they are: drop notes in brackets.
for (const k of ['contact_title', 'contact2_title']) o[k] = o[k].replace(/\s*\([^)]*\)/g, '').trim();
const hook = o.personalisation_hook || (backfill ? String(lead['Personalisation Hook'] || '').trim() : '');

if (!parsed || !hook) {
  // Research failed. A new lead is marked as failed; an older lead keeps its stage and is not tried again.
  const update = backfill
    ? { 'Lead ID': lead['Lead ID'], 'Contact Source': 'Bilinmiyor (araştırma tekrarlanamadı)', 'Last Updated': now }
    : { 'Lead ID': lead['Lead ID'], Stage: 'Research failed', 'Last Updated': now };
  return { json: { error: error || 'No personalisation hook found', update, child: null, stage: update.Stage || lead.Stage, company: lead.Company } };
}

const seg = SEG[o.segment_class] || null;
const employees = num(o.employees);
const exportM = num(o.export_usd_m);
const bespoke = employees != null && employees > 2500;
let fit = '';
let stage = 'Researched';
if (seg && seg[1] === 'Hariç') { fit = 'Uygun değil: kapsam dışı'; stage = 'Not eligible'; }
else if (seg && seg[1] === '2') stage = 'Parked - Wave 2';
else if (seg && seg[1] === 'Ayrı liste') stage = 'Parked - Sourcing office';
else if (bespoke) { fit = 'Kişiye özel (2.500+ çalışan)'; stage = 'Parked - Bespoke'; }
else if (employees != null && employees < 100 && exportM != null && exportM < 5) { fit = 'Uygun değil: ölçek küçük'; stage = 'Not eligible'; }
// Eligible needs one figure at or above the floor (100 staff or about 5 million USD export). One small figure with the other unknown stays open.
else if (!((employees != null && employees >= 100) || (exportM != null && exportM >= 5))) fit = 'Ölçek bilinmiyor';
else fit = 'Uygun';

// Contact 1: the person found (or the one already on file); the email falls back to the general address.
const keep = (fresh, old) => (String(fresh || '').trim() || (backfill ? String(old || '').trim() : ''));
const name1 = keep(o.contact_name, lead['Contact Name']);
const general = isEmail(o.general_email) ? o.general_email.toLowerCase() : '';
const email1 = (isEmail(o.email) ? o.email.toLowerCase() : '') || (backfill ? String(lead.Email || '').trim().toLowerCase() : '') || general;
const role1 = /data/.test(o.contact_role.toLowerCase()) ? 'Veri sorumlusu' : 'Karar verici';
const update = {
  'Lead ID': lead['Lead ID'],
  'Research Notes': backfill && String(lead['Research Notes'] || '').trim() ? String(lead['Research Notes']) : o.research_notes,
  'Personalisation Hook': hook,
  'Contact Name': name1,
  'Contact Title': keep(o.contact_title, lead['Contact Title']),
  Email: email1,
  LinkedIn: keep(o.linkedin, lead.LinkedIn),
  Stage: stage,
  'Last Updated': now,
  'Product Type': o.product_type || String(lead['Product Type'] || ''),
  Employees: employees != null ? String(employees) : '',
  'Export Volume': o.export_volume,
  'Criteria Fit': fit,
  Bespoke: bespoke ? 'Yes' : '',
  'Contact Role': name1 ? role1 : '',
  'Contact Source': source(o.contact_source, !!name1),
  'General Email': general,
  'Contact 2 Name': o.contact2_name,
  'Contact 2 Title': o.contact2_title,
  'Contact 2 Email': isEmail(o.contact2_email) ? o.contact2_email.toLowerCase() : '',
  'Contact 2 LinkedIn': o.contact2_linkedin,
};
if (seg) { update.Segment = seg[0]; update.Wave = seg[1]; }
if (!backfill) update.Language = ['turkey', 'türkiye', 'turkiye'].includes(String(lead.Country || '').trim().toLowerCase()) ? 'tr' : 'en';

// Second contact as its own row, so it gets its own draft, approval, send and follow-ups. If no second person was
// found, the second step goes to the general address (greeting to the team). Not for brands (Nil has not decided
// who the second contact is there), and never to the same address as the first mail.
let child = null;
const childId = String(lead['Lead ID']).trim() + '-B';
const isBrand = seg && seg[0] === 'Marka';
if (stage === 'Researched' && !isBrand && !existingIds.has(childId)) {
  const person2 = !!update['Contact 2 Email'] && update['Contact 2 Email'] !== email1;
  const email2 = person2 ? update['Contact 2 Email'] : (general && general !== email1 ? general : '');
  if (email2) {
    child = {
      'Lead ID': childId,
      Company: lead.Company || '', Website: lead.Website || '', Country: lead.Country || '',
      Segment: update.Segment || lead.Segment || '',
      'Contact Name': person2 ? o.contact2_name : '',
      'Contact Title': person2 ? o.contact2_title : '',
      Email: email2,
      LinkedIn: person2 ? o.contact2_linkedin : '',
      'Research Notes': update['Research Notes'],
      'Personalisation Hook': hook,
      Language: update.Language || lead.Language || '',
      Stage: 'Waiting - 2nd contact',
      'Last Updated': now,
      'Source URL': lead['Source URL'] || '', 'Source Date': lead['Source Date'] || '', Confidence: lead.Confidence || '',
      'Parent Lead ID': lead['Lead ID'],
      Wave: update.Wave || lead.Wave || '',
      'Product Type': update['Product Type'],
      Employees: update.Employees, 'Export Volume': update['Export Volume'], 'Criteria Fit': fit, Bespoke: '',
      'Contact Role': person2 ? 'Veri sorumlusu' : '',
      'Contact Source': person2 ? source(o.contact2_source, true) : 'Genel adres',
      'General Email': general,
    };
  }
}
return { json: { output: o, update, child, stage, company: lead.Company } };

