// Telegram summary of this run: what was researched and where each company went under Nil's rules of 23 Nov 2026.
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const picked = $('Limit 10').all().map(i => i.json || {});
const byId = {};
for (const r of picked) byId[r['Lead ID']] = r;
const rows = $input.all().map(i => i.json || {});
if (!rows.length) return [];
const name = (r) => esc((byId[r['Lead ID']] || {}).Company || r['Lead ID']);
const stageOf = (r) => r.Stage || (byId[r['Lead ID']] || {}).Stage || '';
const group = (s) => rows.filter(r => stageOf(r) === s);
const ready = group('Researched');
const lines = ['<b>Texprove: researched ' + rows.length + ' compan' + (rows.length === 1 ? 'y' : 'ies') + '</b>'];
lines.push(ready.length + ' ready for drafting' + (ready.length ? ': ' + ready.map(name).join(', ') : ''));
const second = ready.filter(r => String(r['Contact 2 Email'] || '').trim()).length;
if (second) lines.push(second + ' of them with a named second contact');
const noEmail = ready.filter(r => 'Email' in r && !String(r.Email || '').trim());
if (noEmail.length) lines.push(noEmail.length + ' without an email (will be blocked): ' + noEmail.map(name).join(', '));
for (const [stage, label] of [['Parked - Wave 2', 'parked for wave 2 (fabric, yarn, home textile, workwear)'], ['Parked - Sourcing office', 'sourcing offices (separate list)'], ['Parked - Bespoke', 'over 2,500 employees (write by hand)'], ['Not eligible', 'not eligible (too small or out of scope)'], ['Research failed', 'research failed']]) {
  const g = group(stage);
  if (g.length) lines.push(g.length + ' ' + label + ': ' + g.map(name).join(', '));
}
return [{ json: { text: lines.join('\n').slice(0, 4000) } }];

// Chooses which leads are researched in this run (Nil's decisions of 23 Nov 2026).
// 1. 'Researched' leads from before the new rules ('Contact Source' still empty): researched again for segment,
//    size and the second contact, so WF2 can draft them. Their existing contact, email and hook are kept.
// 2. 'New' leads from WF0.
// Second-contact rows (with 'Parent Lead ID') are never researched on their own.
const backfill = [];
const fresh = [];
for (const i of $input.all()) {
  const j = i.json || {};
  if (String(j['Parent Lead ID'] || '').trim()) continue;
  const stage = String(j.Stage || '').trim();
  if (stage === 'Researched' && !String(j['Contact Source'] || '').trim()) backfill.push({ json: { ...j, _mode: 'backfill' } });
  else if (stage === 'New') fresh.push({ json: { ...j, _mode: 'new' } });
}
return backfill.concat(fresh);
